UPDATE meal_recipes SET daily_menu_note = 'Thực đơn bổ máu 2.100 kcal dưới đây được xây dựng với tỷ lệ năng lượng từ glucid, protein và lipid là 52:18:30, đồng thời phân bổ cân đối giữa các bữa chính và bữa phụ. Sự kết hợp giữa thịt, hải sản, rau củ, trái cây và các món giàu vi chất giúp khẩu phần thêm đa dạng, hỗ trợ bổ sung dưỡng chất cần thiết cho quá trình tạo hồng cầu và duy trì thể trạng:', daily_menu_items = '[{"slot":"Sáng","dish":"Bún bò","note":"1 khẩu phần","energy":"600"},{"slot":"Sáng","dish":"Cà phê – Sữa","note":"1 khẩu phần","energy":null},{"slot":"Sáng","dish":"Trái cây: Táo","note":"1/2 trái","energy":null},{"slot":"Phụ 1","dish":"Bánh quy + phô mai","note":"Mỗi người:1 cái bánh quy + 1 miếng phô mai tam giác","energy":"250"},{"slot":"Trưa","dish":"Canh gà củ sen (115kcal)","note":null,"energy":"650"},{"slot":"Trưa","dish":"Salad Tonkatsu (130 kcal)","note":"","energy":null},{"slot":"Trưa","dish":"Cải thìa xào hải sâm (95 kcal)","note":"","energy":null},{"slot":"Trưa","dish":"Cơm","note":"1,5 chén","energy":null},{"slot":"Trưa","dish":"Tráng miệng: Thanh long","note":"1/4 trái","energy":null},{"slot":"Phụ 2","dish":"Bánh bông lan","note":"1 cái","energy":"150"},{"slot":"Tối","dish":"Lẩu lươn kèo nèo","note":"1 khẩu phần","energy":"450"},{"slot":"Tối","dish":"Ăn kèm Bún tươi","note":"2 chén","energy":null},{"slot":"Tối","dish":"Trái cây: Mít","note":"4 múi trung bình","energy":null}]' WHERE id = 'recipe-canh-ga-cu-sen';
